import numpy as np
from flowio import FlowData

DET = ['V450-A','V525-A','B530-A','B710-A','YG586-A','YG780-A','R670-A','R780-A']
FLUO = ['BV421','Zombie Aqua','FITC','PerCP-Cy5.5','PE','PE-Cy7','APC','APC-Cy7']
PRIM = {'BV421':'V450-A','Zombie Aqua':'V525-A','FITC':'B530-A','PerCP-Cy5.5':'B710-A',
        'PE':'YG586-A','PE-Cy7':'YG780-A','APC':'R670-A','APC-Cy7':'R780-A'}

def load(path):
    f = FlowData(path); t = f.text; n = int(t['par'])
    names = [t[f'p{i}n'] for i in range(1, n+1)]
    arr = np.asarray(f.events, dtype=np.float64).reshape(-1, n)
    volts = {}
    for i in range(1, n+1):
        v = t.get(f'p{i}v')
        if v is not None:
            volts[names[i-1]] = float(v)
    return names, arr, t, volts

def dets(names):
    return np.array([names.index(d) for d in DET], int)

def otsu(x, bins=8192):
    h, e = np.histogram(x, bins=bins)
    p = h/h.sum(); m = (e[:-1]+e[1:])/2
    w0 = np.cumsum(p); w1 = 1-w0
    s = np.cumsum(p*m); tot = s[-1]
    m0 = s/np.maximum(w0, 1e-12)
    m1 = (tot-s)/np.maximum(w1, 1e-12)
    sb = w0*w1*(m0-m1)**2
    return float(m[int(np.argmax(sb))])
